```json
{
  "data_catalog": [
    {
      "dataset": "sla_log",
      "description": "نتیجهٔ پایبندی به سطح خدمات به تفکیک سیستم",
      "dimensions": [
        "system",
        "month"
      ],
      "measures": [
        "met",
        "breached",
        "total"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "sla_compliance",
      "description": "پایبندی به سطح خدمات",
      "formula": "تعداد برآورده تقسیم بر کل",
