    },
    {
      "system": "سیستم مالی",
      "total": 139,
      "met": 126,
      "breached": 13,
      "sla_pct": 90.6
    },
    {
      "system": "سیستم انبار",
      "total": 74,
      "met": 55,
      "breached": 19,
      "sla_pct": 74.3
    }
